{
  "items": [
    {
      "title": "Germany Energy Balance Data (1990–2025) – AG Energiebilanzen",
      "url_or_doi": "https://ag-energiebilanzen.de/en/data-and-facts/evaluation-tables-on-the-energy-balance/",
      "justification": "Official German energy balance statistics covering the 2010s and 2020s. Includes primary energy consumption, energy supply, electricity generation, fossil fuels, renewable energy, and energy consumption by sector. Particularly useful for analyzing Germany's energy transition, changes in fossil fuel dependence, and long-term energy consumption trends."
    },
    {
      "title": "Germany Electricity Generation and Energy Market Data – Fraunhofer ISE Energy-Charts",
      "url_or_doi": "https://energy-charts.info/downloads.html",
      "justification": "Provides downloadable historical electricity generation and market data for Germany, including solar, wind, coal, natural gas, nuclear, and other energy sources. Covers relevant years in the 2010s and 2020s, with detailed time-series information. Suitable for examining renewable energy expansion, electricity prices, and changes in Germany's electricity generation mix."
    },
    {
      "title": "Eurostat Complete Energy Balances (1990–2024)",
      "url_or_doi": "https://doi.org/10.2908/nrg_bal_c",
      "justification": "Comprehensive annual energy balance dataset covering Germany from 1990 through 2024. Includes energy production, imports, exports, transformation, and final consumption across individual energy products. Allows detailed analysis of Germany's energy supply, fossil fuel dependence, renewable energy adoption, and sectoral energy consumption during both decades."
    },
    {
      "title": "Eurostat Simplified Energy Balances (1990–2024)",
      "url_or_doi": "https://doi.org/10.2908/nrg_bal_s",
      "justification": "Provides harmonized annual statistics on energy production, consumption, imports, exports, and energy transformation. Germany-specific observations are available for 2010–2024. Useful for comparing energy consumption across economic sectors and examining structural changes in Germany's energy system."
    },
    {
      "title": "Germany Renewable Energy Statistics – Umweltbundesamt (German Environment Agency)",
      "url_or_doi": "https://www.umweltbundesamt.de/themen/klima-energie/erneuerbare-energien/erneuerbare-energien-in-zahlen",
      "justification": "Official German government statistics on renewable energy development, including electricity, heating, and transport. Provides historical time series covering the 2010s and 2020s, with downloadable data from the Working Group on Renewable Energy Statistics (AGEE-Stat). Useful for studying solar, wind, hydropower, biomass, and Germany's renewable energy transition."
    },
    {
      "title": "Renewable Energy Sources in Germany – Federal Ministry for Economic Affairs and Energy",
      "url_or_doi": "https://www.bundeswirtschaftsministerium.de/Redaktion/DE/Dossier/erneuerbare-energien.de",
      "justification": "Official government resource providing access to statistics and historical time series on renewable energy development in Germany. Includes information on installed renewable generation capacity, renewable electricity production, and renewable energy use in heating and transport. Relevant for analyzing renewable energy growth throughout the 2010s and 2020s."
    },
    {
      "title": "Eurostat Economy-Wide Material Flow Accounts (1990–2025)",
      "url_or_doi": "https://doi.org/10.2908/env_ac_mfa",
      "justification": "Highly relevant natural resources dataset covering domestic extraction, imports, exports, and consumption of materials. Includes biomass, metal ores, non-metallic minerals, and fossil energy materials. Germany-specific observations cover the 2010s and 2020s. Useful for studying natural resource extraction, resource efficiency, material consumption, and Germany's transition toward a circular economy."
    },
    {
      "title": "Eurostat Domestic Material Consumption per Capita",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/ten00137/default/bar?lang=en",
      "justification": "Provides annual indicators of domestic material consumption per person, including Germany. Derived from Eurostat's material flow accounts, the dataset helps measure natural resource use relative to population. Useful for evaluating resource efficiency, material demand, and sustainable consumption patterns during the 2010s and 2020s."
    },
    {
      "title": "Germany Energy Use by Economic Activity – Federal Statistical Office (Destatis)",
      "url_or_doi": "https://data.europa.eu/data/datasets/https%3A-genesis.destatis.de-genesisws-downloads-00-tables-85121-0002_00",
      "justification": "Official German statistical dataset describing energy use by production area and energy source. Supports analysis of industrial energy consumption, differences between economic activities, and reliance on particular energy sources. Relevant for examining structural changes in Germany's economy and energy consumption during the requested period."
    },
    {
      "title": "Germany Electricity Market Data – Bundesnetzagentur SMARD",
      "url_or_doi": "https://www.smard.de/en/datennutzung",
      "justification": "Official German electricity market data platform providing downloadable information about electricity generation, consumption, wholesale prices, and cross-border electricity flows. Includes historical observations relevant to the 2010s and 2020s. Particularly useful for studying the electricity market, renewable generation variability, energy security, and developments following the 2022 European energy crisis."
    },
    {
      "title": "Germany Core Energy Market Data Register (Marktstammdatenregister) – Bundesnetzagentur",
      "url_or_doi": "https://www.bundesnetzagentur.de/EN/Areas/Energy/CoreEnergyMarketDataRegister/start.html",
      "justification": "Official register of German electricity and gas market installations, including renewable energy generation facilities. Contains information about installed capacity, technology, locations, and commissioning dates. Historical installation records make it useful for analyzing solar and wind power expansion during the 2010s and 2020s, including geographic differences in renewable energy deployment."
    },
    {
      "title": "Germany Renewable Energy Data – Fraunhofer Institute for Solar Energy Systems",
      "url_or_doi": "https://www.ise.fraunhofer.de/en/renewable-energy-data.html",
      "justification": "Research institute data resource providing access to detailed information on renewable electricity generation and electricity market developments in Germany. Relevant for examining changes in renewable generation, electricity supply composition, and energy market behavior during the 2010s and 2020s."
    },
    {
      "title": "Germany Renewable Electricity Generation (1990–2023)",
      "url_or_doi": "https://www.volker-quaschning.de/datserv/ren-Strom-D/index_e.php",
      "justification": "Historical renewable electricity generation dataset covering Germany from 1990 through 2023. Includes electricity produced from individual renewable sources and the renewable share of total electricity generation. Particularly useful for long-term comparisons between the 2010s and early 2020s and for analyzing the growth of wind, solar, hydroelectric, and biomass electricity."
    },
    {
      "title": "Germany Renewable Energy Data – Extractive Industries Transparency Initiative (D-EITI)",
      "url_or_doi": "https://d-eiti.de/en/data/data-on-renewable-energies/",
      "justification": "German transparency initiative providing access to renewable energy statistics and related information, drawing on official AGEE-Stat data. Useful for studying the development of renewable energy resources and understanding the relationship between natural resource governance and Germany's energy transition during the 2010s and 2020s."
    },
    {
      "title": "Germany Renewable Energy Share in Final Energy Consumption – European Environment Agency",
      "url_or_doi": "https://www.eea.europa.eu/en/europe-environment-2025/countries/germany/renewable-energy-sources/",
      "justification": "Country-specific environmental indicator resource tracking renewable energy's contribution to Germany's final energy consumption. Supports analysis of Germany's progress toward renewable energy targets and comparison with broader European trends. Relevant for evaluating renewable energy development across the 2010s and 2020s."
    }
  ]
}
